style.css:
@-moz-document domain("google.com") {
/* 
       STRAY KIDS 'MAXIDENT' GOOGLE THEME 
       Replace the URL in the background-image below with your own image link.
    */
    
    body {
        background-image: url("https://unsplash.com") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Maxident Neon Pink & Dark Accents */
    #searchform, .gLFyf, .RNNXgb {
        background-color: rgba(20, 20, 20, 0.85) !important;
        border: 2px solid #ff1675 !important; /* Maxident Pink */
        box-shadow: 0 0 15px rgba(255, 22, 117, 0.4) !important;
        border-radius: 24px !important;
    }

    /* Search Text Color */
    .gLFyf, input {
        color: #ffffff !important;
        font-family: 'Courier New', Courier, monospace, sans-serif !important;
    }

    /* Google Logo Customization (Glitch/Pink vibe overlay) */
    .lnXpfc, .k1zDcd {
        filter: drop-shadow(0px 0px 10px #ff1675) hue-rotate(320deg) brightness(1.2) !important;
    }

    /* Buttons and Links */
    .RNmpXc, .gNO89b, .Kxw7sc a {
        background-color: #ff1675 !important;
        color: #ffffff !important;
        border: none !important;
        font-weight: bold !important;
        border-radius: 8px !important;
        transition: 0.3s ease !important;
    }

    .RNmpXc:hover, .gNO89b:hover {
        background-color: #b8004f !important;
        box-shadow: 0 0 10px #ff1675 !important;
        transform: scale(1.05);
    }

    /* Footer and Header Text */
    .uU7dJb, .pHiOh, a.gb_ia, a.gb_ja {
        color: #ffffff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
    }
}
